}", "tools/contact_notes.py": """"Add a note to a contact from its plain text. The notes endpoint takes {id, note_b64}, the text base64url-encoded."""
import json

NOTES_URL = 'https://api.hubapi.com/crm/v3/objects/contacts/notes'


def add_contact_note(ctx, args):
    encoded = ctx.call_tool('base64_encode', {'text': str(args.get('text', ''))})
    if encoded.is_error:
        return encoded.output
    body = {'id': args.get('contact_id'), 'note_b64': encoded.output}
    result = ctx.call_tool('api_fetch', {'method': 'POST', 'url': NOTES_URL, 'body': json.dumps(body)})
    return result.output
